package GUI;
import Program.enums.ExpenseCategory; import Program.model.*; import Program.service.ExpenseService; import javafx.beans.property.SimpleStringProperty; import javafx.collections.*; import javafx.collections.transformation.FilteredList; import javafx.scene.control.*; import javafx.scene.layout.*; import java.time.LocalDate; import java.util.Arrays;
public class ExpenseUI extends ScrollPane {private final User user;private final ExpenseService service=new ExpenseService();private final TableView<Expense>table=new TableView<>();private final ObservableList<Expense>source=FXCollections.observableArrayList();private final FilteredList<Expense>filtered=new FilteredList<>(source,e->true);
 public ExpenseUI(User user,MainUI app){this.user=user;setFitToWidth(true);VBox p=UIFactory.page("Expenses","Track, search, filter and manage every outgoing payment.");TextField search=UIFactory.field("Search description or category");ComboBox<String>category=new ComboBox<>();category.getItems().add("All categories");category.getItems().addAll(Arrays.stream(ExpenseCategory.values()).map(ExpenseCategory::getLabel).toList());category.setValue("All categories");DatePicker date=new DatePicker();Button add=UIFactory.button("+ Add Expense","primary-button");HBox f=new HBox(10,search,category,date,add);HBox.setHgrow(search,Priority.ALWAYS);setup();refresh();Runnable filter=()->filtered.setPredicate(e->(search.getText().isBlank()||(e.getDescription()+" "+e.getCategory()).toLowerCase().contains(search.getText().toLowerCase()))&&(category.getValue().equals("All categories")||e.getCategory().equals(category.getValue()))&&(date.getValue()==null||e.getDate().equals(date.getValue())));search.textProperty().addListener((o,a,b)->filter.run());category.valueProperty().addListener((o,a,b)->filter.run());date.valueProperty().addListener((o,a,b)->filter.run());add.setOnAction(e->edit(null));p.getChildren().addAll(f,table);setContent(p);}
 private void setup(){table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_NEXT_COLUMN);column("Date",e->e.getDate().toString());column("Category",Expense::getCategory);column("Description",Expense::getDescription);column("Amount",e->String.format("- ৳%,.0f",e.getAmount()));TableColumn<Expense,Void>a=new TableColumn<>("Actions");a.setCellFactory(c->new TableCell<>(){final Button edit=UIFactory.button("Edit","secondary-button"),delete=UIFactory.button("Delete","danger-button");final HBox buttons=new HBox(5,edit,delete);{edit.setOnAction(e->ExpenseUI.this.edit(getTableView().getItems().get(getIndex())));delete.setOnAction(e->{Expense expense=getTableView().getItems().get(getIndex());if(confirm("Delete expense?")){service.delete(expense.getId());refresh();}});}@Override protected void updateItem(Void item,boolean empty){super.updateItem(item,empty);setGraphic(empty?null:buttons);}});table.getColumns().add(a);table.setItems(filtered);}private void column(String title,java.util.function.Function<Expense,String>value){TableColumn<Expense,String>c=new TableColumn<>(title);c.setCellValueFactory(x->new SimpleStringProperty(value.apply(x.getValue())));table.getColumns().add(c);}private void refresh(){source.setAll(service.loadExpenses(user.getId()));}
 private void edit(Expense old){Dialog<ButtonType>d=new Dialog<>();d.setTitle(old==null?"Add Expense":"Edit Expense");TextField amount=UIFactory.field("Amount"),description=UIFactory.field("Optional description");ComboBox<String>cat=new ComboBox<>();cat.getItems().addAll(Arrays.stream(ExpenseCategory.values()).map(ExpenseCategory::getLabel).toList());DatePicker date=new DatePicker(LocalDate.now());if(old!=null){amount.setText(String.valueOf(old.getAmount()));cat.setValue(old.getCategory());date.setValue(old.getDate());description.setText(old.getDescription());}GridPane form=new GridPane();form.setHgap(10);form.setVgap(10);form.addRow(0,new Label("Amount"),amount);form.addRow(1,new Label("Category"),cat);form.addRow(2,new Label("Date"),date);form.addRow(3,new Label("Description"),description);d.getDialogPane().setContent(form);d.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,ButtonType.OK);d.showAndWait().filter(x->x==ButtonType.OK).ifPresent(x->{try{if(cat.getValue()==null||date.getValue()==null)throw new IllegalArgumentException("Please select a category and date.");double value=Program.utils.Validator.positiveAmount(amount.getText());if(old==null)service.add(user.getId(),value,cat.getValue(),date.getValue(),description.getText());else service.update(old,value,cat.getValue(),date.getValue(),description.getText());refresh();}catch(Exception ex){UIFactory.error(ex.getMessage());}});}
 private boolean confirm(String message){return new Alert(Alert.AlertType.CONFIRMATION,message,ButtonType.YES,ButtonType.NO).showAndWait().orElse(ButtonType.NO)==ButtonType.YES;}
}
